-- Stage 12: additive migration; run only after backup and review on latest server.
CREATE TABLE IF NOT EXISTS crm_leads (id bigserial PRIMARY KEY, customer_email text NOT NULL, interest text NOT NULL, stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','contacted','quoted','won','lost')), assigned_to text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commercial_quotes (id bigserial PRIMARY KEY, customer_email text NOT NULL, revision integer NOT NULL DEFAULT 1 CHECK(revision>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','accepted','expired','superseded')), items jsonb NOT NULL, total_piasters bigint NOT NULL CHECK(total_piasters>=0), currency text NOT NULL DEFAULT 'EGP', valid_until timestamptz, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contract_templates (id bigserial PRIMARY KEY, title text NOT NULL, body text NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_contracts (id bigserial PRIMARY KEY, quote_id bigint NOT NULL REFERENCES commercial_quotes(id), template_id bigint REFERENCES contract_templates(id), body_snapshot text NOT NULL, status text NOT NULL DEFAULT 'issued' CHECK(status IN ('issued','signed','void')), signer_name text, signed_at timestamptz, signature_evidence jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commercial_invoices (id bigserial PRIMARY KEY, quote_id bigint NOT NULL REFERENCES commercial_quotes(id), amount_piasters bigint NOT NULL CHECK(amount_piasters>=0), due_at timestamptz, status text NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','part_paid','paid','void')), verified_paid_piasters bigint NOT NULL DEFAULT 0 CHECK(verified_paid_piasters>=0), provider_reference text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(verified_paid_piasters<=amount_piasters));
CREATE TABLE IF NOT EXISTS service_subscriptions (id bigserial PRIMARY KEY, customer_email text NOT NULL, service_code text NOT NULL, price_piasters bigint NOT NULL CHECK(price_piasters>=0), renews_at timestamptz, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','paused','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS support_tickets (id bigserial PRIMARY KEY, customer_email text NOT NULL, subject text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','waiting_customer','resolved','closed')), assigned_to text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS delivery_requests (id bigserial PRIMARY KEY, quote_id bigint NOT NULL REFERENCES commercial_quotes(id), method text NOT NULL CHECK(method IN ('git','zip')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','delivered')), artifact_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage_ledger (id bigserial PRIMARY KEY, customer_email text NOT NULL, assistant_id text NOT NULL, model text NOT NULL, input_tokens bigint NOT NULL CHECK(input_tokens>=0), output_tokens bigint NOT NULL CHECK(output_tokens>=0), cost_piasters bigint NOT NULL CHECK(cost_piasters>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS crm_leads_email_idx ON crm_leads(customer_email);
CREATE INDEX IF NOT EXISTS quotes_email_idx ON commercial_quotes(customer_email);
CREATE INDEX IF NOT EXISTS tickets_email_idx ON support_tickets(customer_email);
CREATE INDEX IF NOT EXISTS ai_usage_customer_idx ON ai_usage_ledger(customer_email,created_at);
-- Public/customer endpoints must use verified session identity; never trust customer_email supplied by client.
